/* CarePath v2: reference-led portfolio and mobile prototype. Legacy partner flow is retained. */
(() => {
  const mobileKey='carepath-mobile-v2';
  const glyph=(name,size=22)=>`<i data-lucide="${name}" width="${size}" height="${size}" aria-hidden="true"></i>`;
  icon=(name,size=20)=>glyph(({arrow:'arrow-right',back:'arrow-left',check:'check',close:'x',file:'file-text',shield:'shield-check',person:'user-round',chat:'message-circle',download:'download',help:'circle-help',clock:'clock',eye:'eye',folder:'folder',sound:'volume-2',leaf:'leaf'})[name]||'file-text',size);
  brand=()=>'<a class="v2-brand" href="#case">CarePath</a>';
  header=active=>`<header class="cp-top"><div class="v2-wrap cp-top-inner">${brand()}<nav aria-label="Main navigation">${[['case',t('Case study','作品集')],['prototype',t('Prototype','手机原型')],['collaboration',t('Caregivers','照护协作')],['system',t('Design system','设计系统')],['research-plan',t('Research','研究计划')]].map(([id,label])=>`<a href="#${id}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><button class="v2-language" data-action="lang" aria-label="${t('Switch to Chinese','切换为英文')}">${t('中文','EN')}</button></div></header>`;
  footer=()=>`<footer class="v2-footer"><span>CarePath · ${t('Independent product design concept','独立产品设计概念')}</span><a href="#research-plan">${t('Research is planned, not yet conducted','研究已规划，尚未开展')}</a></footer>`;
  const meta=(label,value)=>`<div><strong>${label}</strong><span>${value}</span></div>`;
  const link=(label,href,primary=false)=>`<a href="${href}" class="btn ${primary?'primary':'secondary'}">${label}${glyph('arrow-right',18)}</a>`;

  const principles=()=>[
    {id:1,target:'design-read',icon:'file-text',short:t('Start with the letter','先处理眼前的问题'),question:t('What does this letter mean?','这份文件是什么意思？'),title:t('Start with the immediate problem and lower the entry barrier.','先处理眼前的问题，降低开始的门槛。'),copy:t('An older adult may arrive with a letter, an amount, and a question. “Read my letter” starts with what the document is, what the amount means, and what remains uncertain. Understanding comes before collecting more information.','用户往往带着一封信、一个金额和一个疑问而来。因此入口是“帮我读文件”，接着回答：这是什么文件、金额代表什么、哪些信息还不能确定。先建立理解，再收集后续需要的信息。'),decision:t('Product response: a document-led entry, a plain-language explanation, and access to the source.','产品回应：从文件进入，提供白话解释，并保留原文核对入口。')},
    {id:2,target:'design-check',icon:'list-checks',short:t('Confirm one step at a time','拆成能确认的小步骤'),question:t('What needs checking now?','这一步需要确认什么？'),title:t('Break a complex process into small, confirmable steps.','把复杂流程拆成能确认的小步骤。'),copy:t('Reading, answering, and reviewing are separate steps. Each screen has a clear purpose. Answers remain available for correction, and “not sure” is a valid response, so progress does not depend on guessing.','将阅读解释、补充信息、检查回答分成独立步骤，每一步都有明确目的。已填写的内容可以返回修改，“不确定”也是有效回答，避免用户为了继续而猜测。'),decision:t('Product response: one question per screen, saved answers, and an editable review before continuing.','产品回应：一屏一个问题，保留已有回答，继续前集中检查与修改。')},
    {id:3,target:'design-check',icon:'clipboard-check',short:t('Turn explanation into action','让解释转化为行动'),question:t('What can happen next?','接下来可以做什么？'),title:t('Make the explanation lead to an actionable next step.','让解释能够转化为行动。'),copy:t('Understanding a balance does not automatically explain how to ask for support. A short checklist names the questions to ask, what to keep nearby, and which document requirements still need confirmation.','读懂金额之后，用户仍可能不知道如何咨询。将解释转化为简短的下一步清单：应该向医院询问什么、哪些材料需要准备、哪些要求仍待确认。'),decision:t('Product response: a downloadable question checklist; no unverified promise of eligibility or approval.','产品回应：可保存的咨询清单，明确待核实事项，不将解释包装成援助批准结果。')},
    {id:4,target:'design-help',icon:'headset',short:t('Include human review','把人工介入纳入流程'),question:t('Who checks the uncertainty?','不确定的信息由谁核对？'),title:t('Make human assistance part of the product flow.','把人工介入设计成流程的一部分。'),copy:t('An unreadable amount or unresolved question moves into human review with the existing context. Before a request is created, the person sees the sharing scope and gives permission. The request can be withdrawn.','文件模糊、金额不清或用户无法判断时，保留疑问并转交线上人工核对。求助时携带已有上下文，减少重复解释；共享前说明范围并征得授权，之后可以撤回。'),decision:t('Product response: an explicit handoff, a consented case snapshot, a support workspace, and withdrawal.','产品回应：明确的人工入口、授权后的案例快照、支持工作台与撤回机制。')},
    {id:5,target:'design-help',icon:'users-round',short:t('Define caregiver boundaries','明确照护者的协作边界'),question:t('What help has been authorized?','哪些协助已获得本人同意？'),title:t('Treat caregivers as collaborators and define delegation boundaries.','把照护者视为协作者，明确代办边界。'),copy:t('The older adult selects a caregiver and grants access to one letter, its checklist, or both. Helping organize tasks requires a separate permission. The caregiver can inspect the scope but cannot expand it or take over payments and applications.','老人选择照护者，决定是否共享某一份文件与清单，并单独允许协助整理。照护者只能在授权范围内查看或协助，不能自行扩大权限、代付或提交申请。'),decision:t('Prototype response: document-specific access, optional checklist assistance, and revocation across both phone views. Professional support remains a separate role.','原型回应：限定单份文件、单独选择清单协助权限，撤回后两端同步停止访问；专业人员工作台保持独立。')}
  ];
  function problemMap(){return `<section class="v2-section cp-problem" id="problem" aria-labelledby="problem-heading">
    <div class="cp-problem-intro"><h2 id="problem-heading">${t('Problem | Where the difficulty lies','问题｜困难在哪里')}</h2><p>${t('Medical paperwork can leave three questions unresolved: what the letter means, what to do next, and who can help. CarePath focuses on the gap between understanding a document and preparing to ask for support.','收到医疗费用文件后，用户可能无法判断文件的含义、接下来该做什么，以及可以向谁求助。CarePath 聚焦“读懂文件”与“准备求助”之间的断点。')}</p></div>
    <ul class="cp-problem-questions"><li>${t('Meaning of the letter','读不懂文件与金额')}</li><li>${t('A workable next step','不清楚下一步行动')}</li><li>${t('Help without losing control','求助时难以把握共享与代办范围')}</li></ul>
    <div class="cp-mindmap" aria-label="${t('Five product strategies','五项产品策略导图')}"><div class="cp-map-root"><h3>${t('Understand the letter.<br>Decide the next step.','理解医疗费用文件<br>决定可执行的下一步')}</h3></div><ol class="cp-map-branches">${principles().map(p=>`<li><button type="button" class="cp-map-node" data-strategy-target="${p.target}" aria-controls="${p.target}"><span class="cp-map-number">${p.id}</span>${glyph(p.icon,26)}<h4>${p.short}</h4><p>${p.question}</p><span class="cp-map-destination">${p.target==='design-read'?t('Read the letter','读懂文件'):p.target==='design-check'?t('Check the details','核对内容'):t('Get support','获得协助')}${glyph('arrow-down',15)}</span></button></li>`).join('')}</ol></div>
  </section>`;}

  const rationaleItems=()=>[
    {id:'design-read',image:'flow-choose.jpg',title:t('Read the letter','读懂文件'),copy:t('Start with the document.','先解释手中的文件。'),steps:[1]},
    {id:'design-check',image:'flow-understand.jpg',title:t('Check the details','核对内容'),copy:t('Confirm information and prepare next steps.','逐步确认，形成下一步。'),steps:[2,3]},
    {id:'design-help',image:'flow-help.jpg',title:t('Get support','获得协助'),copy:t('Human review and caregiver permissions.','人工复核与照护者授权。'),steps:[4,5]}
  ];
  function screenCards(){return `<div class="cp-rationale"><div class="cp-rationale-cards">${rationaleItems().map((item,i)=>`<button type="button" class="cp-rationale-card" id="${item.id}" data-rationale="${item.id}" aria-expanded="false" aria-controls="design-rationale"><div class="v2-screen-picture tone-${i}"><img src="assets/${item.image}" alt="" loading="lazy"></div><div class="cp-rationale-caption"><span class="cp-category-index">${i+1}</span><div><h3>${item.title}</h3><p>${item.copy}</p></div><span class="cp-rationale-arrow" aria-hidden="true">${glyph('chevron-down',20)}</span></div></button>`).join('')}</div><section id="design-rationale" class="cp-rationale-panel" aria-label="${t('Design rationale','设计说明')}" hidden></section></div>`;}
  function showRationale(id,force=false){
    const panel=document.getElementById('design-rationale'),trigger=document.getElementById(id);
    if(!panel||!trigger)return;
    const close=!force&&trigger.getAttribute('aria-expanded')==='true';
    document.querySelectorAll('[data-rationale]').forEach(b=>b.setAttribute('aria-expanded',String(!close&&b.id===id)));
    panel.hidden=close;if(close)return;
    const item=rationaleItems().find(x=>x.id===id);
    panel.setAttribute('aria-labelledby',id);
    panel.innerHTML=`<div class="cp-rationale-panel-head"><p>${item.title} · ${t('Design rationale','设计说明')}</p><button type="button" data-rationale-close aria-label="${t('Close design rationale','收起设计说明')}">${glyph('x',18)}</button></div><div class="cp-rationale-articles ${item.steps.length===1?'single':''}">${principles().filter(p=>item.steps.includes(p.id)).map(p=>`<article><h4><span>${p.id}</span>${p.title}</h4><p>${p.copy}</p><p class="cp-rationale-response">${p.decision}</p></article>`).join('')}</div><a class="v2-text-link" href="${id==='design-help'?'#collaboration':'#prototype'}">${id==='design-help'?t('Explore caregiver permissions','体验照护者授权'):t('Explore the prototype','查看交互原型')}${glyph('arrow-right',16)}</a>`;
    panel.querySelector('[data-rationale-close]').addEventListener('click',()=>{showRationale(id);trigger.focus({preventScroll:true});});
    applyIcons();
    if(matchMedia('(max-width:600px)').matches)panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});
  }
  const careStoryStages=()=>[
      {id:'authorize',title:t('Older adult authorizes','老人授权'),alt:t('Mary selects document, checklist and assistance permissions for Anna.','Mary 为 Anna 选择文件、清单与协助操作权限。'),older:t('Choose Anna, set the scope, and explicitly confirm.','选择 Anna、设置范围，并明确确认同意。'),caregiver:t('No access before confirmation.','确认前无法访问共享内容。'),before:t('Not shared','默认不共享'),after:t('Confirmation activates access','本人确认后生效')},
      {id:'assist',title:t('Caregiver views and helps','照护者查看与协助'),alt:t('Anna uses the authorized checklist and adds a consultation question.','Anna 在授权的清单中标记任务并补充咨询问题。'),older:t('Review progress; change or revoke access.','查看协作进展，可调整范围或撤回。'),caregiver:t('View selected content. Task updates and questions need separate permission.','查看指定内容；单独获准后，才能标记任务、补充问题。'),before:t('Selected content only','仅限指定内容'),after:t('Actions need permission','协助操作单独授权')},
      {id:'revoked',title:t('Older adult revokes','老人撤回'),alt:t('Mary has revoked access. Anna can no longer view shared content.','Mary 撤回授权后，Anna 的手机显示授权已结束，无法再访问共享内容。'),older:t('Confirm revocation; keep personal documents and progress.','确认撤回，保留本人的文件与协作记录。'),caregiver:t('Viewing and editing stop. Access cannot be restored by the caregiver.','文件、清单与操作入口停止访问，不能自行恢复授权。'),before:t('Access ended','访问停止'),after:t('Owner records retained','老人记录保留')}
  ];
  function careStoryPanel(stage){return `<figure class="cp-story-phone tone-${stage.id}"><img src="assets/care-story-${stage.id}-${state.lang}.webp" width="393" height="852" alt="${stage.alt}" loading="eager" decoding="async"></figure><div class="cp-story-detail"><h3>${stage.id==='authorize'?t('Access starts after confirmation','确认后才开放访问'):stage.id==='assist'?t('Viewing and actions are separate permissions','查看与操作分别授权'):t('Access stops; the owner keeps their records','停止访问，保留本人记录')}</h3><dl class="cp-story-capabilities"><div><dt>${t('Older adult','老人')}</dt><dd>${stage.older}</dd></div><div><dt>${t('Caregiver','照护者')}</dt><dd>${stage.caregiver}</dd></div></dl><div class="cp-story-permission" aria-label="${t('Permission change','权限变化')}"><span>${stage.before}</span>${glyph('arrow-right',16)}<strong>${stage.after}</strong></div><p class="cp-story-boundary">${glyph('shield-check',17)}${t('No payments, applications, or onward delegation. Revocation cannot recall saved copies.','不包含代付、提交申请或再次转授权；撤回无法追回已保存的副本。')}</p></div>`;}
  function caseCareStory(){const stages=careStoryStages();return `<section class="v2-section cp-case-care" id="caregiver-story" aria-labelledby="care-story-heading"><div class="cp-case-care-heading"><div><h2 id="care-story-heading">${t('Caregiver collaboration','照护者协作')}</h2><p>${t('The older adult controls the scope. Assistance stays within that scope, and access can be revoked.','由老人决定共享范围，照护者按权限协助；撤回后访问停止，已有记录保留。')}</p></div><a class="v2-text-link" href="#collaboration">${t('Try both phone views','操作双端原型')}${glyph('arrow-right',17)}</a></div><ol class="cp-case-care-stages" aria-label="${t('Authorization, assistance and revocation','授权、协助与撤回流程')}">${stages.map((stage,i)=>`<li><button type="button" data-care-stage="${stage.id}" aria-pressed="${i===0}" aria-controls="care-story-panel"><span class="cp-story-step">${i+1}</span><span><strong>${stage.title}</strong><small>${stage.id==='authorize'?t('No access before consent','确认前不开放访问'):stage.id==='assist'?t('Only the authorized scope','只在授权范围内操作'):t('Access ends immediately','访问立即停止')}</small></span></button>${i<2?glyph('arrow-right',19):''}</li>`).join('')}</ol><div id="care-story-panel" class="cp-story-panel" aria-live="polite">${careStoryPanel(stages[0])}</div></section>`;}
  function showCareStory(id){const stage=careStoryStages().find(s=>s.id===id),panel=document.getElementById('care-story-panel');if(!stage||!panel)return;document.querySelectorAll('[data-care-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.careStage===id)));panel.innerHTML=careStoryPanel(stage);applyIcons();}

  casePage=()=>`${header('case')}<main id="main" tabindex="-1" class="v2 v2-wrap">
    <section class="v2-hero"><div><h1>CarePath</h1><h2>${t('Understanding medical bills.<br>Preparing for support.','理解医疗费用文件，<br>准备下一步求助。')}</h2><p>${t('A mobile concept for older adults and caregivers to understand medical paperwork, check information, and prepare a support conversation.','帮助老年用户与照护者读懂医疗费用文件、核对信息，并准备咨询与求助。')}</p><div class="v2-actions">${link(t('Explore the app','体验手机原型'),'#prototype',true)}<a class="v2-text-link" href="#problem">${t('Product design approach','查看设计思路')}</a></div></div><figure><img src="assets/carepath-context.webp" alt="${t('Older adult comparing a letter and a phone at home','老年人在家中对照文件与手机')}" fetchpriority="high"><figcaption>${t('AI-generated illustrative scene','AI 生成的场景示意')}</figcaption></figure></section>
    <div class="v2-meta">${meta(t('Audience','目标用户'),t('Adults 65+ and caregivers','65 岁以上用户与照护者'))}${meta(t('Scope','项目范围'),t('Document understanding + support preparation','文件理解与求助准备'))}${meta(t('Status','项目状态'),t('Concept · research planned','概念原型 · 研究待开展'))}</div>
    ${problemMap()}
    <section class="v2-section" id="overview"><div class="v2-section-heading"><h2>${t('Five strategies.<br>Three connected parts of the experience.','五项产品策略，<br>落在三组连续的体验中。')}</h2><p class="cp-disclosure-hint">${t('Select a category for its design rationale.','选择分类，查看下方设计说明。')}</p></div>${screenCards()}</section>
    <section class="v2-section"><div class="v2-section-heading"><h2>${t('The interaction flow','交互流程')}</h2>${link(t('Open the prototype','查看原型'),'#prototype')}</div><div class="v2-flow" aria-label="User flow">${[t('Choose a sample','选择文件'),t('Read + check','阅读与核对'),t('Confirm details','补充必要信息'),t('Review answers','检查与修改'),t('Save next steps','保存行动清单')].map((n,i)=>`<div><span>${i+1}</span><strong>${n}</strong>${i<4?glyph('arrow-right',18):''}</div>`).join('')}</div><div class="v2-handoff"><div class="v2-handoff-symbol">${glyph('user-round',34)}</div><div><h3>${t('Human review remains available throughout the flow.','人工复核贯穿流程，保留求助时的上下文。')}</h3><p>${t('Sharing scope, consent and withdrawal are separate from preparing a checklist.','共享范围、明确授权与撤回操作，独立于行动清单的准备。')}</p></div><a class="v2-text-link" href="#partners">${t('Support workspace','支持工作台')}${glyph('arrow-right',18)}</a></div></section>
    ${caseCareStory()}
    <section class="v2-section v2-research-teaser"><div><h2>${t('Research plan','研究计划')}</h2><p>${t('The planned study evaluates document comprehension, next-step clarity, and control over human or caregiver assistance.','计划通过访谈与任务测试，验证文件理解、下一步行动的清晰度，以及人工与照护者协作中的控制感。')}</p>${link(t('View the research protocol','查看研究方案'),'#research-plan',true)}</div><div class="v2-research-preview"><div><strong>4</strong><span>${t('older adults · planned','老年用户 · 计划')}</span></div><div><strong>2</strong><span>${t('caregivers · planned','照护者 · 计划')}</span></div><p>${t('Separate sessions, followed by prototype changes and a second round of testing.','两组分别访谈与测试，基于观察修改原型，并开展第二轮复测。')}</p></div></section>${footer()}</main>`;

  const careState={older:null,caregiver:null};
  function collaborationNotes(role,screen,data,sheet=''){
    const share=data?.careShare||{},active=share.status==='active';
    let stage,action,result;
    if(role==='caregiver'){
      stage=t('Caregiver','照护者端');
      if(!active){action=share.status==='revoked'?t('Access revoked','授权已撤回'):t('Waiting for authorization','等待授权');result=t('The letter, checklist and editing controls are unavailable. Access cannot be restored by the caregiver.','文件、清单与操作入口均不可访问；照护者不能自行恢复权限。');}
      else if(screen==='care-document'){action=t('Read the shared letter','查看共享文件');result=t('Only the authorized document snapshot is shown. Revocation also clears an already-open document view.','仅展示授权的那一份文件；即使文件已经打开，撤回后也会停止显示。');}
      else if(screen==='care-scope'){action=t('Inspect permission boundaries','查看权限边界');result=t('The caregiver can inspect the granted scope but cannot expand it, pay, submit applications, or delegate onward.','可查看已有权限，不能扩大授权、代付、提交申请或再次转授权。');}
      else{action=share.manage?t('Help organize the checklist','协助整理清单'):t('Read authorized content','查看已授权内容');result=share.manage?t('Task updates and an added question appear in the older adult’s collaboration progress. Both actions require current checklist-management permission.','可标记任务和补充问题，老人端同步显示进展；两项操作均需有效的清单管理权限。'):t('Only selected content is shown. Task changes and question entry remain unavailable until separately authorized.','只显示选中的内容；未单独允许协助整理时，不能更改任务或补充问题。');}
    }else{
      stage=t('Older adult','老人端');
      const descriptions={
        'care-recipient':[t('Choose a caregiver','选择照护者'),t('Choosing Anna does not share content. The next step defines the scope.','选择 Anna 不会立即共享，下一步才设置授权范围。')],
        'care-permissions':[t('Set viewing and action permissions','设置查看与操作范围'),t('Letter access, checklist viewing and checklist management are separate. At least one viewing scope is required. Draft changes take effect only after confirmation.','文件查看、清单查看与协助整理分别设置；至少选择一种查看范围，修改草稿在确认后才生效。')],
        'care-review':[t('Review and confirm consent','核对并明确同意'),t('The selected person, document and scope are shown together. Authorization remains unavailable until consent is checked.','集中展示照护者、文件与权限；明确勾选同意前，不能确认授权。')]
      };
      if(sheet==='care-revoke'){action=t('Confirm revocation','确认撤回');result=t('A confirmation explains future access will stop and saved copies cannot be recalled. Access remains active until confirmation.','确认前说明停止后续访问、已保存副本无法追回；确认前授权仍有效。');}
      else if(descriptions[screen]){[action,result]=descriptions[screen];}
      else if(share.status==='revoked'){action=t('Access revoked','已撤回授权');result=t('The caregiver loses document and checklist access immediately in both views. The older adult keeps their information and progress.','两端同步取消文件与清单访问；老人本人的信息和已有进展保留。');}
      else if(active){action=t('Manage active access','管理有效授权');result=t('Granted scopes and shared progress are visible. The older adult can change the scope or revoke access at any time.','查看当前授权与协作进展，可随时调整范围或撤回。');}
      else{action=t('Start with no shared access','默认不共享');result=t('The caregiver sees an authorization-required state. Access begins only after the older adult chooses a scope and confirms.','照护者端显示等待授权；老人设置范围并确认后才允许访问。');}
    }
    return `<div class="cp-care-logic-row"><strong>${stage}</strong><div><h4>${action}</h4><p>${result}</p></div></div>`;
  }
  function collaborationPage(){const current=readMobile();return `${header('collaboration')}<main id="main" tabindex="-1" class="v2 v2-wrap cp-care-page"><div class="cp-care-page-heading"><div><h1>${t('Caregiver collaboration','照护者协作')}</h1><p>${t('The older adult chooses the person and scope. Both phone views respond to authorization and revocation.','由老人选择照护者与授权范围，两端同步展示授权、协作和撤回后的变化。')}</p></div></div><section class="cp-care-demo-pair" aria-label="${t('Linked older adult and caregiver prototypes','老人端与照护者端联动原型')}">${[['older',t('Older adult · Mary','老人端 · Mary'),'sharing'],['caregiver',t('Caregiver · Anna','照护者端 · Anna'),'care-view']].map(([role,label,screen])=>`<article class="cp-care-device"><div class="cp-care-device-heading"><h2>${label}</h2><a href="mobile/index.html?flow=care&view=${role}&screen=${screen}&lang=${state.lang}" target="_blank" rel="noopener">${t('Open larger','单独放大')}${glyph('arrow-up-right',15)}</a></div><iframe id="care-${role}" title="${label}" src="mobile/index.html?flow=care&view=${role}&screen=${screen}&lang=${state.lang}"></iframe></article>`).join('')}</section><section class="cp-care-logic" aria-labelledby="care-logic-heading"><h2 id="care-logic-heading">${t('Interaction and permission logic','交互与权限逻辑')}</h2><div id="care-older-logic" aria-live="polite">${collaborationNotes('older','sharing',current)}</div><div id="care-caregiver-logic" aria-live="polite">${collaborationNotes('caregiver','care-view',current)}</div><p class="cp-care-demo-limit">${t('Fictional people and documents. This local prototype simulates permissions; it does not send invitations or provide production account authorization.','使用虚构人物与文件，本地原型模拟权限变化；不发送真实邀请，不提供正式账户授权服务。')}</p></section>${footer()}</main>`;}

  const flowNotes=()=>({
    home:[t('Start','开始'),t('Choose a task','选择任务'),t('A photo gives context. Two large actions: read a letter or ask a person.','场景图帮助理解产品；只提供读文件和真人帮助两个主要选项。'),t('The next screen offers fictional samples.','下一屏提供虚构示例文件。')],
    choose:[t('Letter','文件'),t('Choose a readable or blurry sample','选择清晰或模糊的示例'),t('A document preview makes the choice recognizable. No real upload is requested.','通过预览识别文件，不要求上传真实医疗材料。'),t('A readable sample continues; a blurry one routes toward human review.','清晰文件进入解释，模糊文件引向人工复核。')],
    understand:[t('Explain','解释'),t('Read the amount and check its source','查看金额并核对依据'),t('Show the balance in large type. Put the original and read-aloud action within reach.','用大字号显示余额，提供查看原文和朗读入口。'),t('Prepare questions, choose another sample, or request a person.','准备问题、更换示例，或请求真人协助。')],
    household:[t('Details','补充'),t('Answer one question','一次回答一个问题'),t('Large radio cards show selection. Continue is unavailable until an answer is chosen.','大卡片显示选择状态；作答后才能继续。'),t('Previous answers stay available when going back.','返回时保留已经回答的信息。')],
    income:[t('Details','补充'),t('Say whether a document is ready','说明材料准备情况'),t('“Not sure” is a valid answer. No amount or private document is collected.','“不确定”是有效回答，不收集具体金额或真实文件。'),t('Review answers before preparing the checklist.','先核对回答，再生成清单。')],
    review:[t('Review','核对'),t('Correct an answer before continuing','继续前可修改回答'),t('Edit links are visible. Checking the answers prepares a list, without sharing.','修改入口可见。勾选核对只会准备清单，不会共享。'),t('A separate permission step is needed for human handoff.','人工交接需要单独授权。')],
    next:[t('Next steps','下一步'),t('Save a short, usable checklist','保存简短可用的清单'),t('Mark tasks, download the list, or request help. It is not an application or eligibility result.','勾选任务、下载清单或请求帮助；清单不是申请或资格结果。'),t('The person can inspect or withdraw a review request.','用户可以查看或撤回复核请求。')],
    letters:[t('My letters','我的文件'),t('Return to a saved sample','回到已保存的示例'),t('The letter and next-step list stay accessible. A new demo can be started here.','保留文件和清单入口，并可重新开始演示。'),t('Only fictional scenario choices are saved in this browser.','本浏览器只保存虚构场景选项。')]
  });
  function notes(screen='home'){const n=flowNotes()[screen]||flowNotes().home;return `<div class="v2-current"><span>${n[0]}</span><h3>${n[1]}</h3></div><div class="v2-logic-grid"><article><strong>${t('User action','用户操作')}</strong><p>${n[1]}</p></article><article><strong>${t('System response','系统响应')}</strong><p>${n[2]}</p></article><article><strong>${t('Next / recovery','下一步与恢复')}</strong><p>${n[3]}</p></article></div>`;}
  memberPage=()=>`${header('prototype')}<main id="main" tabindex="-1" class="v2 v2-wrap"><div class="v2-page-head"><div><h1>${t('The member app','会员端 App')}</h1><p>${t('An interactive prototype covering document explanation, information review, and human support. Flow notes follow the active screen.','覆盖文件解释、信息核对与人工求助的交互原型，下方同步呈现当前步骤的逻辑。')}</p></div><div class="v2-scenario"><button class="active" data-demo="home">${t('Start','从头体验')}</button><button data-demo="unclear">${t('Blurry letter','模糊文件')}</button><a href="#partners">${t('Partner view','合作方端')}</a><a href="#collaboration">${t('Caregivers','照护协作')}</a></div></div><section class="v2-demo-grid"><div class="v2-phone-stage"><iframe id="mobile-demo" src="mobile/index.html?lang=${state.lang}" title="${t('Interactive CarePath mobile app','CarePath 手机交互原型')}" allow="autoplay"></iframe></div><aside class="v2-demo-aside"><h2>${t('Designed for reading<br>and doing.','读得清楚，<br>也知道怎么做。')}</h2><div class="v2-demo-features">${[[glyph('type',24),t('20 px main text','20 px 核心正文'),t('23 px larger-text option','支持 23 px 大字模式')],[glyph('hand',24),t('62 px primary actions','62 px 主要操作'),t('Clear text labels on every action','操作均带清晰文字标签')],[glyph('volume-2',24),t('Read or listen','阅读或听取'),t('Source and spoken explanation','原文核对与语音朗读')]].map(([i,h,p])=>`<article>${i}<div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><div class="v2-demo-note"><strong>${t('Unclear-document recovery','模糊文件的异常处理')}</strong><p>${t('An unreadable letter leads to human review, explicit sharing permission, and a reversible request.','文件无法辨认时，进入人工复核、明确共享授权，并提供撤回路径。')}</p></div><p class="v2-disclosure">${t('Concept prototype. Scripted explanations, fictional documents, no real application submission.','概念原型：解释为脚本，文件为虚构，不提交真实申请。')}</p></aside></section><section class="v2-logic"><div class="v2-section-heading"><h2>${t('Interaction logic','交互逻辑')}</h2><span id="v2-current-step">${t('Current screen','当前屏幕')}</span></div><div id="v2-logic-content" aria-live="polite">${notes()}</div></section>${footer()}</main>`;

  systemPage=()=>`${header('system')}<main id="main" tabindex="-1" class="v2 v2-wrap"><div class="v2-page-head"><div><h1>${t('CarePath design system','CarePath 设计系统')}</h1><p>${t('The same colors, cards, and controls used in the working app.','与实际 App 共用的颜色、卡片与操作控件。')}</p></div>${button(t('Download tokens','下载令牌'),'tokens','secondary','','download')}</div><section class="v2-section v2-system-top"><div class="v2-type-card"><h2>${t('Readable at the start','默认就清晰易读')}</h2><p class="v2-type-sample">${t('Understand your medical bill','读懂你的医疗账单')}</p><p class="v2-body-sample" id="v2-type-example">${t('The letter shows $186 left to pay.','文件显示尚需支付 $186。')}</p><button class="btn secondary" data-action="v2-size" aria-pressed="false">${t('Try larger text','试试大字模式')}</button><div class="v2-type-labels"><span>34 px / ${t('Heading','标题')}</span><span>20 px / ${t('Body','正文')}</span><span>23 px / ${t('Larger','大字')}</span></div></div><div class="v2-ui-spec"><img src="assets/flow-understand.jpg" alt="${t('Actual app screen with large amount and rounded cards','实际 App 中的大字号与圆角卡片')}"><div><strong>24 px</strong><span>${t('Card radius','卡片圆角')}</span><strong>62 px</strong><span>${t('Primary touch target','主要触控区域')}</span></div></div></section><section class="v2-section"><h2>${t('Color with a purpose','颜色有明确的职责')}</h2><div class="v2-palette">${[['pine','#21483E',t('Main action','主要操作')],['sage','#E7EEE3',t('Explanation','解释信息')],['peach','#FFE3D0',t('Attention','提醒注意')],['white','#FFFFFF',t('Content','内容表面')],['ink','#1B2924',t('Main text','主要文字')],['error','#A03227',t('Error','错误状态')]].map(([cl,hex,role])=>`<div><span class="color-${cl}"></span><strong>${role}</strong><code>${hex}</code></div>`).join('')}</div></section><section class="v2-section"><h2>${t('Working components','可操作的组件')}</h2><div class="v2-component-grid"><article><h3>${t('Actions','操作')}</h3><div class="stack">${button(t('Continue','继续'),'ds-continue','primary','','arrow')}${button(t('Back','返回'),'ds-back','secondary','','back')}${button(t('Choose an answer first','请先选择回答'),'none','primary','disabled')}</div></article><article><h3>${t('Required field + recovery','必填与错误恢复')}</h3><form id="ds-form" novalidate><div class="field"><label for="ds-name">${t('Sample name','示例名字')}</label><input id="ds-name" placeholder="Mary" aria-describedby="ds-error"></div><p id="ds-error" class="error-message" role="alert"></p><button class="btn secondary" type="submit">${t('Check field','检查字段')}</button></form></article><article><h3>${t('Explicit permission','明确的授权')}</h3><label class="check-row"><input type="checkbox" id="ds-consent"><span>${t('Share this sample for review.','共享此示例以供复核。')}<small>${t('The letter, checked answers, and your question.','文件、已核对的回答与你的问题。')}</small></span></label><p id="ds-consent-status" class="small muted">${t('Nothing is shared.','未共享任何内容。')}</p></article><article><h3>${t('State + next action','状态与下一步')}</h3><div class="v2-state-row"><span>${t('Needs review','需要复核')}</span>${glyph('arrow-right',18)}<span>${t('In review','复核中')}</span></div><p>${t('An unreadable amount stays unknown. A person checks the source.','无法辨认的金额保持未知，由真人核对原文。')}</p><a class="v2-text-link" href="#prototype">${t('Try the blurry sample','体验模糊文件分支')}</a></article></div></section><section class="v2-section"><h2>${t('Checks and limits','检查与边界')}</h2><div class="v2-checks"><p>${glyph('check',20)}${t('Visible keyboard focus and named controls','可见键盘焦点与带标签的控件')}</p><p>${glyph('check',20)}${t('Reduced-motion support and persistent help','支持减少动态效果，帮助入口始终可见')}</p><p>${glyph('check',20)}${t('Browser QA is separate from real user testing','浏览器检查与真实用户测试分开报告')}</p></div><p class="v2-disclosure">${t('Real iOS / Android hardware, assistive technology, and older participants still need to be tested.','仍需在真实 iOS / Android 设备、辅助技术和老年参与者中验证。')}</p></section>${footer()}</main>`;

  const inviteEN='Hi! I’m working on CarePath, a design concept to help older adults understand medical paperwork. Would you be interested in a 45–60 minute conversation and a short phone-prototype test? We will use fictional sample letters, so you do not need to share medical records, bills, income, or passwords. This is a design study, not benefits enrollment or medical advice. Participation is voluntary; you can skip questions or stop at any time. Any thank-you payment will be explained in advance and will not depend on finishing the tasks. May I send you a short information sheet and arrange a time?';
  const inviteZH='你好，我在做一个帮助老年人理解医疗费用文件的设计概念 CarePath。想邀请你参加约45–60分钟的交流，并体验一个手机原型。我们只用虚构示例，不需要提供真实病历、账单、收入或密码。这是设计研究，不是福利申请或医疗咨询。参加完全自愿，可以跳过问题或随时停止。如果提供感谢费，会提前说明，且不以完成任务为条件。你有兴趣先看一份简短介绍，再约时间吗？';
  const interviewOlder=['最近一次收到医疗费用或保险相关文件时，你先做了什么？','其中哪些地方容易理解，哪些地方让你停下来？请举一个具体例子。','你怎样判断一份文件需要立即处理，还是可以之后再看？','你通常如何求助？当时是谁做了哪些事情？','用手机处理这类事情时，最近遇到过什么困难？','在分享一份文件之前，你会想知道哪些信息？','如果电脑解释和你理解的不一致，你会怎样核实？','你希望哪些决定自己做，哪些事情希望别人帮助？'];
  const interviewCare=['最近一次帮别人处理费用文件时，你接手了哪一步？','你如何知道对方已经理解，或只是答应了？','哪些信息经常需要重复询问或重新寻找？','你怎样确认自己有权查看或分享对方的信息？','如果一个助手把任务转交给你，你最需要收到什么？'];
  const tasks=()=>[
    ['T1',t('Understand the letter','理解文件'),t('Mary received this sample letter. Find out what it says and tell me what you would do next.','Mary 收到这份示例文件。请了解它的意思，并告诉我你接下来会做什么。'),t('Finds $186 and its source; does not mistake the amount for assistance approval.','找到 $186 及其依据；不把金额误认为援助批准。')],
    ['T2',t('Handle missing information','处理缺失信息'),t('Prepare questions for Mary. She lives alone and does not know whether her income document is ready.','为 Mary 准备咨询问题。她独居，不确定收入证明是否准备好了。'),t('Chooses “not sure”, continues, and can explain why no real income amount is needed.','选择“不确定”并继续；理解无需输入真实收入金额。')],
    ['T3',t('Correct an answer','修改回答'),t('Before you finish, Mary says she lives with family. Update the answer.','完成前，Mary 说自己其实与家人同住。请修改回答。'),t('Locates Edit, changes the answer, returns to review with other answers preserved.','找到修改入口，更新回答，其他回答仍保留。')],
    ['T4',t('Ask a person about a blurry letter','模糊文件求助'),t('This second letter is hard to read. Get help. Before agreeing, tell me what will be shared and with whom.','第二份文件看不清，请获得帮助。同意前，请说明会共享什么、共享给谁。'),t('Finds human review; understands letter + answers + question; consent precedes request.','找到人工复核；理解文件、回答和问题的共享范围；授权后才创建请求。')],
    ['T5',t('Withdraw and keep next steps','撤回并保留下一步'),t('Mary changes her mind about sharing. Cancel the request, then keep a copy of what she can do next.','Mary 改变了共享的主意。请取消请求，并保留一份下一步清单。'),t('Withdraws the active request; finds/downloads checklist; understands no application was submitted.','撤回活跃请求，找到并下载清单，理解尚未提交申请。')]
  ];
  function researchPage(){
    const olderEN=[
      'What did you do the last time you received a medical bill or insurance letter?',
      'Which parts were clear, and where did you pause? Can you describe an example?',
      'How did you decide whether something needed immediate action?',
      'Who helped, and what did each person do?',
      'What was difficult about using your phone for that task?',
      'What would you want to know before sharing a document?',
      'How would you check an explanation that differed from your understanding?',
      'Which decisions would you want to make yourself, and where would you welcome help?'
    ];
    const careEN=[
      'Which part did you take over the last time you helped with a medical letter?',
      'How did you tell whether the person understood or was simply agreeing?',
      'Which information had to be requested or found again?',
      'How did you confirm permission to view or share their information?',
      'What context would you need when receiving a request for help?'
    ];
    const list=items=>`<ol>${items.map(x=>`<li>${x}</li>`).join('')}</ol>`;
    const disclosure=(title,body)=>`<details><summary>${title}</summary>${body}</details>`;
    const section=(heading,body)=>`<section class="v2-section"><h2>${heading}</h2>${body}</section>`;
    return `${header('research-plan')}<main id="main" tabindex="-1" class="v2 v2-wrap v2-research">
      <div class="v2-page-head"><div><h1>${t('Interview & usability<br>test plan','真实用户访谈<br>与可用性测试计划')}</h1><p>${t('A proposed study of document comprehension, support preparation, and caregiver collaboration.','围绕文件理解、求助准备与照护者协作的研究方案。')}</p></div><div class="v2-actions">${button(t('Download the plan','下载完整计划'),'v2-research-download','primary','','download')}${button(t('Print','打印'),'v2-print','secondary')}</div></div>
      <p class="v2-research-status">${t('Planned study · Participant research has not yet been conducted.','计划中的研究 · 尚未开展参与者访谈与可用性测试。')}</p>
      <section class="v2-recruit-summary"><div><strong>4</strong><span>${t('older adults','老年用户')}</span></div><div><strong>2</strong><span>${t('caregivers','照护者')}</span></div><div><strong>45–60</strong><span>${t('minutes per session','分钟 / 场')}</span></div><p>${t('Separate sessions for each audience. A second round includes two returning older adults and one new older adult after prototype revisions.','两组分别进行。原型修改后，计划邀请2位原参与老人和1位新老年用户复测。')}</p></section>
      ${section(t('1. Research questions','1. 研究问题'),`<div class="v2-portfolio-evidence">${[
        [t('Comprehension and action','理解与行动'),t('Can participants explain the document accurately and identify a practical next step?','参与者能否准确复述文件含义，并找到可执行的下一步？')],
        [t('Control during assistance','求助中的控制感'),t('Can they explain what is shared, who receives it, and how to withdraw? What role should a caregiver play?','能否理解共享内容、接收对象与撤回方式？照护者应在哪些环节协助？')]
      ].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`)}
      ${section(t('2. Recruitment and participant mix','2. 招募方式与样本构成'),`<p>${t('Convenience sampling and participant referrals. Six to eight initial invitations target four older adults and two caregivers, with variation in phone confidence and support needs.','采用便利抽样与转介绍，首批联系6–8人，目标约到4位老人和2位照护者，覆盖不同手机熟练度与支持需要。')}</p>${disclosure(t('Screening and recruitment criteria','筛选与招募条件'),list([
        t('Adults aged 65+ or caregivers who have helped an older person with paperwork in the past six months. Age is recorded in bands.','65岁以上用户，或过去6个月协助老人处理过文件的照护者；年龄仅记录区间。'),
        t('The proposed mix includes two older adults who often need phone assistance and two more independent users; caregivers may include family and regular or professional helpers.','计划覆盖2位较常需要手机操作帮助的老人、2位较独立使用者；照护者可包括家属与经常协助或有相关工作经验的人。'),
        t('Scheduling confirms language, device, accessibility needs, location and breaks. Assistive-technology users are included.','排期前确认语言、设备、无障碍支持、地点与休息需要，纳入辅助技术使用者。'),
        t('Older adults and caregivers are interviewed separately where practical. Any assistance during testing is recorded.','尽量分开访谈；测试中的陪同与协助均记录。'),
        t('If the sample is outside the US or uses Chinese, findings apply to the tested language and interaction context, not to the broader Medicare population or English medical terminology.','若实际样本不在美国或主要使用中文，结论仅适用于所测试的语言与交互情境，不外推至整体Medicare人群或英文医疗术语理解。')
      ]))}${disclosure(t('Participant invitation template','参与者邀请模板'),`<p id="invite-content">${state.lang==='zh'?inviteZH:inviteEN}</p><div class="v2-actions">${button(t('Copy English','复制英文'),'v2-invite-en','secondary')}${button(t('Copy Chinese','复制中文'),'v2-invite-zh','secondary')}</div>`)}`)}
      ${section(t('3. Session structure','3. 访谈与测试场次'),`<div class="v2-session">${[['5 min',t('Introduction + consent','说明与同意')],['15 min',t('Recent-experience interview','访谈近期经历')],['25 min',t('Prototype tasks','原型任务')],['5 min',t('Reflection + thanks','复盘与致谢')]].map(([n,l])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><p>${t('Sessions allow ten minutes of flexibility, with breaks or early stopping. Familiar devices and in-person sessions are preferred; remote sessions begin with a connection check.','场次预留10分钟弹性，可休息或提前结束。优先使用熟悉的设备并现场进行；远程场次先做连接检查。')}</p>
        <div class="v2-research-columns"><article><h3>${t('Older adult interview','老年用户访谈问题')}</h3>${list(state.lang==='zh'?interviewOlder:olderEN)}</article><article><h3>${t('Caregiver interview','照护者访谈问题')}</h3>${list(state.lang==='zh'?interviewCare:careEN)}<p class="v2-research-tip">${t('Follow-up prompts ask for concrete examples and what happened next. Product preference questions follow the experience interview.','追问以具体例子和后续行为为主，产品偏好问题放在经历访谈之后。')}</p></article></div>
        ${disclosure(t('Consent, privacy and moderator introduction','知情同意、隐私与主持开场'),`<p>${t('“Today we are testing the design, not you. We will use fictional letters. No application will be made and no hospital will be contacted. You may skip questions or stop at any time.”','“今天测试的是设计，不是在考你。我们使用虚构文件，不会提交申请或联系医院。你可以跳过问题，也可以随时停止。”')}</p>${list([
          t('Participation, recording and use of anonymous quotations require separate consent. Declining recording does not prevent participation.','研究参与、录音录屏、匿名引语使用分别征求同意；拒绝录制仍可参与。'),
          t('The information sheet states the researcher, purpose, duration, data collected, withdrawal method, contact channel and retention period.','说明书列明研究者、目的、时长、收集内容、退出方式、联系渠道与保留期限。'),
          t('The proposed retention period deletes recordings and contact details within 30 days of study completion. Anonymous notes follow the agreed portfolio-use terms.','拟在研究结束30天内删除录音与联系信息，匿名笔记按事先约定的用途保留。'),
          t('Only fictional samples are used. Real medical records, income, insurance numbers, passwords and diagnoses are not collected. Contact details are stored separately from notes.','仅使用虚构样本，不收集真实病历、收入、保险号、密码或诊断；联系方式与研究笔记分开保存。'),
          t('Any thank-you payment is disclosed in advance and is independent of task completion. Planning allowance: $30–50 per first-round session, $180–300 for six sessions; retest incentives are budgeted separately.','感谢费事先说明，且不以完成任务为条件。预算示例：首轮每场30–50美元，6场共180–300美元；复测感谢费另计。')
        ])}`)}
      `)}
      ${section(t('4. Usability tasks and success criteria','4. 可用性任务与完成标准'),`<p>${t('Tasks use fictional documents and scenario-based prompts without naming interface controls. T1–T4 take priority if fatigue or time limits the session.','使用虚构文件与情境式任务，不直接提示控件位置。出现疲劳或时间不足时，优先完成T1–T4。')}</p><div class="v2-task-list">${tasks().map(([id,h,task,success])=>`<article><span>${id}</span><div><h3>${h}</h3><p>${task}</p>${disclosure(t('Observation criteria','观察与完成标准'),`<p>${success}</p>`)}</div></article>`).join('')}</div>
        <article class="v2-demo-note"><h3>${t('Caregiver follow-up task','照护者补充任务')}</h3><p>${t('A family member asks for help with this sample. Explain the step to assist with, which actions need their permission, and which decisions remain theirs.','家人请照护者帮助处理示例文件：说明会协助哪一步、哪些操作需要先征得本人同意，以及哪些决定仍由本人作出。')}</p><p>${t('The study examines explanation versus task takeover and missing context. The prototype now includes document-specific permission, optional checklist assistance and revocation. Real account verification and invitation delivery remain outside the prototype.','重点观察解释与接管之间的区别，以及协作所需的上下文。原型已包含文件范围授权、可选的清单协助与撤回；真实账户验证和邀请送达仍在原型范围之外。')}</p></article>
        ${disclosure(t('Assistance and moderation protocol','提示等级与主持原则'),`<p>${t('Hesitation, requests for help and the point of intervention are recorded. Time is diagnostic; there is no speed threshold. A non-leading prompt may follow a pause of about 20 seconds.','记录犹豫、求助与介入发生点。时间用于诊断，不设置完成速度门槛；停顿约20秒后可采用非引导性追问。')}</p>${list([
          t('A0: completed independently, without prompts.','A0：无提示，独立完成。'),t('A1: task restated without naming controls.','A1：仅重述任务，不指出控件。'),t('A2: a general prompt such as “What are you thinking now?”','A2：一般性追问，如“你现在在想什么？”'),t('A3: a specific control or action identified; recorded as assisted completion.','A3：指出具体控件或操作，计为协助完成。')
        ])}<p>${t('The amount-versus-approval question follows the participant’s own explanation to avoid teaching the answer first.','金额是否代表援助批准的问题，放在参与者自行复述之后，避免提前教给答案。')}</p>`)}`)}
      ${section(t('5. Observation and analysis','5. 观察记录与证据分析'),`<div class="v2-evidence-chain"><span>${t('Observation','实际观察')}</span>${glyph('arrow-right',20)}<span>${t('Interpretation','解释与假设')}</span>${glyph('arrow-right',20)}<span>${t('Design change','设计修改')}</span>${glyph('arrow-right',20)}<span>${t('Retest','复测证据')}</span></div><p>${t('Records include participant code, task, observed behavior, permitted quotations, assistance level, outcome, interpretation, severity, proposed change and retest evidence. Observation and interpretation remain separate.','记录字段包括参与者编号、任务、行为、经同意的原话、提示等级、完成情况、解释、严重度、拟修改内容与复测证据；实际观察与原因假设分开记录。')}</p><div class="v2-severity">${[
        ['P0',t('Critical misunderstanding or loss of control, such as interpreting the amount as approval or being unable to withdraw.','关键误解或控制问题，如将金额当成援助批准、无法撤回共享。')],
        ['P1',t('A primary task is blocked or human help cannot be found.','主要任务无法完成，或找不到人工帮助。')],
        ['P2',t('Repeated mis-taps, difficult reading, or poor recovery.','反复误点、阅读困难或恢复不顺畅。')],
        ['P3',t('A preference that does not affect task completion.','不影响任务完成的个人偏好。')]
      ].map(([h,p])=>`<p><strong>${h}</strong>${p}</p>`).join('')}</div><p>${t('Older-adult and caregiver results are reported separately as counts within the sample. Critical misconceptions and blocked tasks take priority over visual preferences.','老年用户与照护者分组分析，以样本内人数呈现结果。优先解决关键误解与任务阻断，再处理视觉偏好。')}</p>${button(t('Download a blank observation log','下载空白观察记录'),'v2-log','secondary','','download')}`)}
      ${section(t('6. Reporting and design iteration','6. 研究呈现与设计迭代'),`<div class="v2-portfolio-evidence">${[
        [t('Sample and method','对象与方法'),t('Actual dates, sample, age bands, language, recruitment and limitations.','实际日期、人数、年龄区间、语言、招募来源与局限。')],
        [t('Evidence behind decisions','改变设计的证据'),t('A traceable observation linked to a design decision, supported by permitted anonymous quotations or behavior notes.','可追溯的观察对应设计决定，附经同意的匿名引语或行为记录。')],
        [t('Before and after','修改前后对比'),t('The same screen and task, annotated changes and the outcome of retesting.','相同页面与任务的前后截图、修改说明与复测结果。')],
        [t('Remaining uncertainty','仍未验证的部分'),t('Convenience sampling, scripted explanations, limited devices and no real assistance outcome.','便利样本、脚本化解释、有限设备，以及尚无真实援助结果。')]
      ].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><p class="v2-research-status">${t('Evidence status: planned. Observations, revisions and retest results will be reported after the study.','证据状态：研究待开展。观察、设计修改与复测结果将在研究完成后报告。')}</p>`)}
      ${section(t('7. Proposed schedule · 7–10 days','7. 计划安排 · 7–10天'),list([
        t('Day 1: finalize scenarios, consent and materials; run one pilot excluded from formal findings.','第1天：确定任务、同意说明与材料，完成1次预演；预演不混入正式结果。'),
        t('Days 2–4: schedule and run four older-adult and two caregiver sessions, usually one or two per day.','第2–4天：完成4位老人、2位照护者的独立场次，每天约1–2场。'),
        t('Days 4–6: consolidate notes, group evidence and prioritize up to three key issues.','第4–6天：整理笔记、归类证据，选出最多3个优先问题。'),
        t('Days 7–8: revise and retest with two returning older adults and one new older adult; record possible learning effects.','第7–8天：修改原型，邀请2位原参与老人、1位新老人复测，记录学习效应。'),
        t('Days 9–10: document method, evidence, changes and limitations. Timing adjusts to recruitment progress.','第9–10天：整理研究方法、证据、前后对比与局限，排期根据实际招募进度调整。')
      ]))}
      <section class="v2-section v2-sources"><h3>${t('Method references','方法参考')}</h3><a href="https://www.w3.org/WAI/test-evaluate/involving-users/" target="_blank" rel="noreferrer">W3C WAI · Involving users in accessibility evaluation</a><a href="https://www.w3.org/WAI/older-users/" target="_blank" rel="noreferrer">W3C WAI · Older users and accessibility</a><a href="https://www.gov.uk/service-manual/user-research/using-moderated-usability-testing" target="_blank" rel="noreferrer">GOV.UK · Moderated usability testing</a><a href="https://www.gov.uk/service-manual/user-research/getting-users-consent-for-research" target="_blank" rel="noreferrer">GOV.UK · Informed consent</a></section>${footer()}</main>`;
  }


  route=()=>{const id=location.hash.slice(1).split('/')[0];return ['case','prototype','collaboration','partners','system','research-plan'].includes(id)?id:id.startsWith('ds-')?'system':'case';};
  function applyIcons(){window.lucide?.createIcons({attrs:{'stroke-width':1.7}});}
  function readMobile(){try{return JSON.parse(localStorage.getItem(mobileKey)||'null');}catch{return null;}}
  function mergeMobile(data){if(!data)return;Object.assign(state,{doc:data.sample,household:data.household||'',income:data.income||'',handoff:!!data.handoff,consent:!!data.consent,partnerStatus:data.partnerStatus||'needs-review',handoffSnapshot:data.handoffSnapshot||null});}
  mergeMobile(readMobile());
  const originalRender=render;
  render=function(options={}){if(route()==='collaboration'){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.title='CarePath — Caregiver collaboration';app.innerHTML=collaborationPage();bind();if(options.top)window.scrollTo({top:0,behavior:'instant'});}else if(route()==='research-plan'){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.title='CarePath — Research plan';app.innerHTML=researchPage();bind();if(options.top)window.scrollTo({top:0,behavior:'instant'});}else originalRender(options);applyIcons();bindV2();save();};
  const originalTokens=actions.tokens;
  actions.tokens=()=>{download('CarePath-v2-tokens.json',JSON.stringify({version:'2.0',colors:{pine:'#21483e',sage:'#e7eee3',peach:'#ffe3d0',canvas:'#f7f8f5',ink:'#1b2924',muted:'#526158',error:'#a03227'},type:{body:20,larger:23,heading:34,button:21},radius:{card:24,photo:32,button:22},spacing:[8,16,24,32,48,72],touchTarget:62},null,2),'application/json');};
  void originalTokens;
  actions['v2-size']=()=>{const e=$('#v2-type-example'),b=$('[data-action="v2-size"]');const large=b.getAttribute('aria-pressed')!=='true';e.classList.toggle('larger',large);b.setAttribute('aria-pressed',String(large));b.textContent=large?t('Return to standard','恢复标准字号'):t('Try larger text','试试大字模式');};
  async function copyInvite(text){try{await navigator.clipboard.writeText(text);notify(t('Invitation copied.','邀请文案已复制。'));}catch{download('CarePath-invitation.txt',text,'text/plain');}}
  actions['v2-invite-en']=()=>copyInvite(inviteEN);actions['v2-invite-zh']=()=>copyInvite(inviteZH);actions['v2-print']=()=>window.print();
  actions['v2-log']=()=>download('CarePath-observation-log.json',JSON.stringify({study:'CarePath formative research',status:'blank template — no findings',participantCode:'',group:'older-adult / caregiver',language:'',device:'',consent:{participation:false,recording:false,anonymousQuote:false},tasks:tasks().map(([id,title])=>({id,title,observedBehavior:'',quoteWithPermission:'',assistanceLevel:'A0 / A1 / A2 / A3',outcome:'independent / assisted / incomplete',interpretation:'',severity:'',proposedChange:'',retestEvidence:''})),limitations:[],retentionDate:''},null,2),'application/json');
  actions['v2-research-download']=()=>{const old=state.lang;state.lang='zh';const content=researchPage();state.lang=old;const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CarePath 研究计划</title><style>body{font:17px/1.7 system-ui,sans-serif;color:#1b2924;max-width:1000px;margin:auto;padding:32px}header,footer,button,.v2-actions{display:none}h1{font-size:38px}h2{font-size:27px;margin-top:48px}h3{font-size:21px}article{padding:16px 0}li{margin:10px 0}details{margin:20px 0}summary{font-weight:700}a{color:#21483e}.v2-research-status{background:#e7eee3;padding:20px}.v2-recruit-summary{padding:24px;background:#f7f8f5}.v2-recruit-summary strong{font-size:30px;margin-right:12px}.v2-recruit-summary>div{display:inline-grid;margin-right:30px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:12px}svg,i{display:none}@media print{body{font-size:12pt;padding:0}details> :not(summary){display:block!important}h2{break-after:avoid}article,li{break-inside:avoid}}</style>${content.replaceAll('<details>','<details open>')}</html>`;download('CarePath-Research-Plan.html',html,'text/html');};
  for(const name of ['begin-review','confirm-guidance','withdraw']){const run=actions[name];actions[name]=(...args)=>{run(...args);const data=readMobile();if(data){Object.assign(data,{handoff:state.handoff,consent:state.consent,partnerStatus:state.partnerStatus,handoffSnapshot:state.handoffSnapshot});localStorage.setItem(mobileKey,JSON.stringify(data));}};}
  function bindV2(){
    document.querySelectorAll('[data-care-stage]').forEach(node=>node.addEventListener('click',()=>showCareStory(node.dataset.careStage)));
    document.querySelectorAll('[data-rationale]').forEach(node=>node.addEventListener('click',()=>showRationale(node.dataset.rationale)));
    document.querySelectorAll('[data-strategy-target]').forEach(node=>node.addEventListener('click',()=>{
      showRationale(node.dataset.strategyTarget,true);
      document.querySelector('.cp-rationale')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
    }));
document.querySelectorAll('[data-demo]').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('[data-demo]').forEach(x=>x.classList.remove('active'));el.classList.add('active');const unclear=el.dataset.demo==='unclear';$('#mobile-demo').src=`mobile/index.html?lang=${state.lang}&screen=${unclear?'understand':'home'}&sample=${unclear?'unclear':'clear'}`;}));}
  window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type==='carepath:collaboration'){const role=e.data.role==='caregiver'?'caregiver':'older';careState[role]=e.data;const target=document.getElementById(`care-${role}-logic`);if(target)target.innerHTML=collaborationNotes(role,e.data.screen,e.data.data,e.data.sheet);else if(document.getElementById('v2-logic-content')){document.getElementById('v2-logic-content').innerHTML=collaborationNotes(role,e.data.screen,e.data.data,e.data.sheet);document.getElementById('v2-current-step').textContent=t('Family collaboration','家人协作');}}if(e.data?.type==='carepath:screen'){mergeMobile(e.data.data);const n=e.data.screen;if($('#v2-logic-content')){$('#v2-logic-content').innerHTML=notes(n);$('#v2-current-step').textContent=(flowNotes()[n]||flowNotes().home)[0];applyIcons();}}if(e.data?.type==='carepath:partner')location.hash='partners';});
  window.addEventListener('storage',e=>{if(e.key===mobileKey){mergeMobile(readMobile());if(route()==='partners')render();}});
  render();
})();
